#!/bin/bash
set -e

# Stage 1 of Invoice WhatsApp integration: verify Puppeteer PDF generation
# actually works on Vercel BEFORE wiring the full send flow on top of it.
# Run this from your veda-hmis repo root in Codespaces.

echo "" | base64 -d > "package.json"
echo "Wrote package.json"

mkdir -p "lib"
echo "" | base64 -d > "lib/pdf-generator.js"
echo "Wrote lib/pdf-generator.js"

mkdir -p "app/api/test-invoice-pdf/[invoiceId]"
echo "" | base64 -d > "app/api/test-invoice-pdf/[invoiceId]/route.js"
echo "Wrote app/api/test-invoice-pdf/[invoiceId]/route.js"

npm install

git add package.json package-lock.json lib/pdf-generator.js "app/api/test-invoice-pdf/[invoiceId]/route.js"
git commit -m "Add Puppeteer-based invoice PDF generation (test stage)"
git push

echo "Done. After Vercel deploys, visit:"
echo "https://portal.vedaeyehospital.com/api/test-invoice-pdf/bf96cb51-46bd-45ad-8562-08665adba446"
